CREATE OR ALTER PROCEDURE [dbo].[uspKpiDailySnapshot_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @BranchId UNIQUEIDENTIFIER = NULL
	, @DataQualityStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[SnapshotDate]
			, t.[BranchId]
			, t.[MetricCode]
			, t.[MetricVersion]
			, t.[MetricValue]
			, t.[Numerator]
			, t.[Denominator]
			, t.[TargetValue]
			, t.[VarianceValue]
			, t.[CalculationVersion]
			, t.[CalculatedAt]
			, t.[SourceWatermark]
			, t.[DataQualityStatus]
			, t.[CreatedDate]
		FROM [dbo].[KpiDailySnapshot] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[MetricCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@BranchId IS NULL OR t.[BranchId] = @BranchId)
			AND (ISNULL(@DataQualityStatus, '') = '' OR t.[DataQualityStatus] = @DataQualityStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'snapshotDate' THEN r.[SnapshotDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'snapshotDate' THEN r.[SnapshotDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'branchId' THEN r.[BranchId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'branchId' THEN r.[BranchId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'metricCode' THEN r.[MetricCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'metricCode' THEN r.[MetricCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'metricVersion' THEN r.[MetricVersion] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'metricVersion' THEN r.[MetricVersion] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'metricValue' THEN r.[MetricValue] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'metricValue' THEN r.[MetricValue] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'numerator' THEN r.[Numerator] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'numerator' THEN r.[Numerator] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'denominator' THEN r.[Denominator] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'denominator' THEN r.[Denominator] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'targetValue' THEN r.[TargetValue] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'targetValue' THEN r.[TargetValue] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'varianceValue' THEN r.[VarianceValue] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'varianceValue' THEN r.[VarianceValue] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'calculationVersion' THEN r.[CalculationVersion] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'calculationVersion' THEN r.[CalculationVersion] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'calculatedAt' THEN r.[CalculatedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'calculatedAt' THEN r.[CalculatedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sourceWatermark' THEN r.[SourceWatermark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sourceWatermark' THEN r.[SourceWatermark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dataQualityStatus' THEN r.[DataQualityStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dataQualityStatus' THEN r.[DataQualityStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
